// ============================================================================
// Constants & Dynamic Scaling Helpers (Up to 200 Yards / 6-Meter Giant Cups)
// ============================================================================

const CUP_TOP_RADIUS = 0.50;      // 1.0 meter base diameter for easy scoring!
const CUP_BOTTOM_RADIUS = 0.36;   // meters
const CUP_HEIGHT = 0.42;          // meters (hanging beneath the elevated tournament deck)
const CUP_SPACING_X = 1.18;       // meters
const CUP_SPACING_Z = 1.02;       // meters (equilateral triangle packing)

const TABLE_WIDTH = 6.8;          // meters (X)
const TABLE_LENGTH = 15.0;        // meters (Z)
const TABLE_HEIGHT = 0.48;        // meters (Y) - elevated 48cm deck so cups hang above ground

export function getScaleForDistance(distYards: number): number {
  if (distYards <= 15) return 1.0;   // 1.0m cup (15y)
  if (distYards <= 30) return 1.4;   // 1.4m cup (30y)
  if (distYards <= 60) return 2.0;   // 2.0m cup (60y)
  if (distYards <= 100) return 3.0;  // 3.0m cup (100y)
  if (distYards <= 150) return 4.5;  // 4.5m cup (150y)
  return 6.0;                        // 6.0m giant stadium pool cup (200y!)
}

export function getBasePointsForDistance(distYards: number): number {
  if (distYards <= 15) return 100;
  if (distYards <= 30) return 150;
  if (distYards <= 60) return 250;
  if (distYards <= 100) return 400;
  if (distYards <= 150) return 700;
  return 1000;
}

export function getClubNameForDistance(distYards: number): string {
  if (distYards <= 15) return 'Chipping Wedge (56\u00B0)';
  if (distYards <= 30) return 'Pitching Wedge (48\u00B0)';
  if (distYards <= 60) return 'Sand / Lob Wedge (58\u00B0)';
  if (distYards <= 100) return '9-Iron / Pitching Wedge';
  if (distYards <= 150) return '6-Iron / 7-Iron';
  return 'Driver / 3-Wood (Max Bomb)';
}

