// ============================================================================
// Procedural Web Audio Synthesizer
// ============================================================================

function initAudio() {
  if (!ctx.audioCtx) {
    const AudioContextClass = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    if (AudioContextClass) {
      ctx.audioCtx = new AudioContextClass();
    }
  }
  if (ctx.audioCtx && ctx.audioCtx.state === 'suspended') {
    ctx.audioCtx.resume();
  }
}

function playAudio(type: 'hit' | 'table_bounce' | 'cup_rim' | 'cup_sink' | 'bounce_bonus' | 'cheer' | 'airball' | 'win' | 'click') {
  if (ctx.audioMuted) return;
  initAudio();
  if (!ctx.audioCtx) return;

  const aCtx = ctx.audioCtx;
  const now = aCtx.currentTime;

  try {
    switch (type) {
      case 'hit': {
        // Crisp club face impact crack
        const osc = aCtx.createOscillator();
        const gain = aCtx.createGain();
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(320, now);
        osc.frequency.exponentialRampToValueAtTime(80, now + 0.08);

        gain.gain.setValueAtTime(0.8, now);
        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.09);

        osc.connect(gain);
        gain.connect(aCtx.destination);
        osc.start(now);
        osc.stop(now + 0.09);
        break;
      }

      case 'table_bounce': {
        // Heavy wooden table clack
        const osc = aCtx.createOscillator();
        const gain = aCtx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(220, now);
        osc.frequency.exponentialRampToValueAtTime(60, now + 0.12);

        gain.gain.setValueAtTime(0.7, now);
        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.13);

        osc.connect(gain);
        gain.connect(aCtx.destination);
        osc.start(now);
        osc.stop(now + 0.13);
        break;
      }

      case 'cup_rim': {
        // High plastic rim clink
        const osc = aCtx.createOscillator();
        const gain = aCtx.createGain();
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(1400, now);
        osc.frequency.exponentialRampToValueAtTime(800, now + 0.07);

        gain.gain.setValueAtTime(0.5, now);
        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.08);

        osc.connect(gain);
        gain.connect(aCtx.destination);
        osc.start(now);
        osc.stop(now + 0.08);
        break;
      }

      case 'cup_sink': {
        // Wet liquid splash & bubble gulp
        const osc = aCtx.createOscillator();
        const gain = aCtx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(450, now);
        osc.frequency.exponentialRampToValueAtTime(200, now + 0.18);

        gain.gain.setValueAtTime(0.9, now);
        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.22);

        osc.connect(gain);
        gain.connect(aCtx.destination);
        osc.start(now);
        osc.stop(now + 0.22);

        // Followed by celebratory chime
        const chime = aCtx.createOscillator();
        const chimeGain = aCtx.createGain();
        chime.type = 'sine';
        chime.frequency.setValueAtTime(587.33, now + 0.08); // D5
        chime.frequency.setValueAtTime(880.00, now + 0.18); // A5
        chimeGain.gain.setValueAtTime(0.4, now + 0.08);
        chimeGain.gain.exponentialRampToValueAtTime(0.01, now + 0.45);

        chime.connect(chimeGain);
        chimeGain.connect(aCtx.destination);
        chime.start(now + 0.08);
        chime.stop(now + 0.45);
        break;
      }

      case 'bounce_bonus': {
        // Two-tone fanfare: bounce shot 2x bonus!
        [523.25, 659.25, 783.99, 1046.5].forEach((freq, i) => {
          const osc = aCtx.createOscillator();
          const gain = aCtx.createGain();
          osc.type = 'triangle';
          osc.frequency.setValueAtTime(freq, now + i * 0.07);

          gain.gain.setValueAtTime(0.5, now + i * 0.07);
          gain.gain.exponentialRampToValueAtTime(0.01, now + i * 0.07 + 0.2);

          osc.connect(gain);
          gain.connect(aCtx.destination);
          osc.start(now + i * 0.07);
          osc.stop(now + i * 0.07 + 0.2);
        });
        break;
      }

      case 'cheer': {
        // Crowd cheer burst
        const bufferSize = aCtx.sampleRate * 0.6;
        const buffer = aCtx.createBuffer(1, bufferSize, aCtx.sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < bufferSize; i++) {
          data[i] = (Math.random() * 2 - 1) * Math.sin((i / bufferSize) * Math.PI);
        }
        const noise = aCtx.createBufferSource();
        noise.buffer = buffer;

        const filter = aCtx.createBiquadFilter();
        filter.type = 'bandpass';
        filter.frequency.setValueAtTime(800, now);
        filter.Q.setValueAtTime(2.0, now);

        const gain = aCtx.createGain();
        gain.gain.setValueAtTime(0.5, now);
        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.6);

        noise.connect(filter);
        filter.connect(gain);
        gain.connect(aCtx.destination);
        noise.start(now);
        break;
      }

      case 'airball': {
        // Groan on airball miss
        const osc = aCtx.createOscillator();
        const gain = aCtx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(160, now);
        osc.frequency.linearRampToValueAtTime(90, now + 0.35);

        gain.gain.setValueAtTime(0.35, now);
        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.4);

        osc.connect(gain);
        gain.connect(aCtx.destination);
        osc.start(now);
        osc.stop(now + 0.4);
        break;
      }

      case 'win': {
        // Grand victory chord arpeggio
        [440, 554.37, 659.25, 880, 1108.73].forEach((f, i) => {
          const osc = aCtx.createOscillator();
          const gain = aCtx.createGain();
          osc.type = 'triangle';
          osc.frequency.setValueAtTime(f, now + i * 0.1);

          gain.gain.setValueAtTime(0.6, now + i * 0.1);
          gain.gain.exponentialRampToValueAtTime(0.01, now + i * 0.1 + 0.7);

          osc.connect(gain);
          gain.connect(aCtx.destination);
          osc.start(now + i * 0.1);
          osc.stop(now + i * 0.1 + 0.7);
        });
        break;
      }

      case 'click': {
        const osc = aCtx.createOscillator();
        const gain = aCtx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(800, now);
        gain.gain.setValueAtTime(0.2, now);
        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.03);
        osc.connect(gain);
        gain.connect(aCtx.destination);
        osc.start(now);
        osc.stop(now + 0.03);
        break;
      }
    }
  } catch (err) {
    console.warn('[Audio] playback error:', err);
  }
}

