  leftStripe.position.set(-TABLE_WIDTH / 2, TABLE_HEIGHT + 0.03, 0);
  tableGroup.add(leftStripe);
  borders.push(leftStripe);

  // Right neon stripe
  const rightStripe = leftStripe.clone();
  rightStripe.position.x = TABLE_WIDTH / 2;
  tableGroup.add(rightStripe);
