function initParticleSystem(scene: THREE.Scene) {
  const maxParticles = 300;
  const positions = new Float32Array(maxParticles * 3);
  const colors = new Float32Array(maxParticles * 3);

  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));

  const mat = new THREE.PointsMaterial({
    size: 0.09,
    vertexColors: true,
    transparent: true,
    opacity: 0.95,
    blending: THREE.AdditiveBlending,
  });

  const points = new THREE.Points(geo, mat);
  points.frustumCulled = false;
  scene.add(points);

  ctx.particlePoints = points;
  ctx.particleGeo = geo;
}

function spawnSplashParticles(centerPos: THREE.Vector3) {
  const count = 50;
  const amberColor = new THREE.Color(0xf59e0b);
  const foamColor = new THREE.Color(0xfffef0);

  for (let i = 0; i < count; i++) {
    const isFoam = Math.random() > 0.55;
    const angle = Math.random() * Math.PI * 2;
    const speed = 1.4 + Math.random() * 3.2;
    const upwardVel = 2.8 + Math.random() * 4.0;

    ctx.splashParticles.push({
      pos: centerPos.clone().add(new THREE.Vector3(
        (Math.random() - 0.5) * 0.3,
        0.1,
        (Math.random() - 0.5) * 0.3
      )),
      vel: new THREE.Vector3(
        Math.cos(angle) * speed,
        upwardVel,
        Math.sin(angle) * speed
      ),
      color: isFoam ? foamColor.clone() : amberColor.clone(),
      size: 0.05 + Math.random() * 0.07,
      life: 0,
      maxLife: 0.85 + Math.random() * 0.55,
    });
  }
}

function updateSplashParticles(delta: number) {
  if (!ctx.particleGeo) return;

  const positions = ctx.particleGeo.attributes.position.array as Float32Array;
  const colors = ctx.particleGeo.attributes.color.array as Float32Array;
  const gravity = -9.8;

  for (let i = ctx.splashParticles.length - 1; i >= 0; i--) {
    const p = ctx.splashParticles[i];
    p.life += delta;
    if (p.life >= p.maxLife) {
      ctx.splashParticles.splice(i, 1);
      continue;
    }

    p.vel.y += gravity * delta;
    p.pos.addScaledVector(p.vel, delta);
  }

  // Update buffer geometry attributes
  let pIdx = 0;
  for (let i = 0; i < ctx.splashParticles.length && pIdx < 300; i++) {
    const p = ctx.splashParticles[i];
    const alpha = 1.0 - (p.life / p.maxLife);

    positions[pIdx * 3] = p.pos.x;
    positions[pIdx * 3 + 1] = p.pos.y;
    positions[pIdx * 3 + 2] = p.pos.z;

    colors[pIdx * 3] = p.color.r * alpha;
    colors[pIdx * 3 + 1] = p.color.g * alpha;
    colors[pIdx * 3 + 2] = p.color.b * alpha;

    pIdx++;
  }

  // Zero out remaining positions
  for (let i = pIdx; i < 300; i++) {
    positions[i * 3 + 1] = -100;
  }

  ctx.particleGeo.attributes.position.needsUpdate = true;
  ctx.particleGeo.attributes.color.needsUpdate = true;
}

// ============================================================================
// Environment, Lighting & Course Setup (Extended to 200+ Yards)
// ============================================================================

function mergeBufferGeometries(geometries: THREE.BufferGeometry[]): THREE.BufferGeometry {
  let totalVerts = 0;
  let totalIndices = 0;
  for (const g of geometries) {
    totalVerts += g.attributes.position.count;
    if (g.index) totalIndices += g.index.count;
    else totalIndices += g.attributes.position.count;
  }

  const positions = new Float32Array(totalVerts * 3);
  const normals = new Float32Array(totalVerts * 3);
  const colors = new Float32Array(totalVerts * 3);
  const indices = new Uint32Array(totalIndices);

  let vOffset = 0;
  let iOffset = 0;

  for (const g of geometries) {
    const pos = g.attributes.position;
    const norm = g.attributes.normal;
    const col = g.attributes.color;
    const count = pos.count;

    positions.set(pos.array as Float32Array, vOffset * 3);
    if (norm) normals.set(norm.array as Float32Array, vOffset * 3);
    if (col) {
      colors.set(col.array as Float32Array, vOffset * 3);
    } else {
      colors.fill(1, vOffset * 3, (vOffset + count) * 3);
    }

    if (g.index) {
      const idxArr = g.index.array;
      for (let j = 0; j < idxArr.length; j++) {
        indices[iOffset + j] = idxArr[j] + vOffset;
      }
      iOffset += idxArr.length;
    } else {
      for (let j = 0; j < count; j++) {
        indices[iOffset + j] = vOffset + j;
      }
      iOffset += count;
    }
    vOffset += count;
  }

  const merged = new THREE.BufferGeometry();
  merged.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  merged.setAttribute('normal', new THREE.BufferAttribute(normals, 3));
  merged.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  merged.setIndex(new THREE.BufferAttribute(indices, 1));
  return merged;
}

function createOrganicBunkerTexture(): THREE.CanvasTexture {
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 512;
  const c = canvas.getContext('2d');
  if (c) {
    c.clearRect(0, 0, 512, 512);
    const lobes = [
      { cx: 195, cy: 256, rx: 145, ry: 125 },
      { cx: 315, cy: 248, rx: 140, ry: 120 },
      { cx: 256, cy: 274, rx: 130, ry: 110 },
    ];
    lobes.forEach((l) => {
      const g = c.createRadialGradient(l.cx, l.cy, l.rx * 0.65, l.cx, l.cy, l.rx);
      g.addColorStop(0.0, 'rgba(138, 114, 72, 0.95)');
      g.addColorStop(0.78, 'rgba(92, 112, 64, 0.65)');
      g.addColorStop(1.0, 'rgba(45, 90, 39, 0.0)');
      c.fillStyle = g;
      c.beginPath();
      c.arc(l.cx, l.cy, l.rx, 0, Math.PI * 2);
      c.fill();
    });
    lobes.forEach((l) => {
      const g = c.createRadialGradient(l.cx - 10, l.cy - 8, 8, l.cx, l.cy, l.rx * 0.82);
      g.addColorStop(0.0, 'rgba(247, 232, 198, 1.0)');
      g.addColorStop(0.65, 'rgba(232, 210, 166, 0.98)');
      g.addColorStop(0.88, 'rgba(186, 156, 104, 0.85)');
      g.addColorStop(1.0, 'rgba(186, 156, 104, 0.0)');
      c.fillStyle = g;
      c.beginPath();
      c.arc(l.cx, l.cy, l.rx * 0.82, 0, Math.PI * 2);
      c.fill();
    });
  }
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

