function getMinimapCupCoords(cup: CupData, w: number, h: number): { cx: number; cy: number } {
  // Match golfer's 3D perspective:
  // +X (relX > 0) is Left (cx < w/2), -X (relX < 0) is Right (cx > w/2).
  // +Z (Row 4 back row, relZ > 0) is Top (cy smaller), -Z (Row 1 front apex, relZ < 0) is Bottom (cy larger, toward golfer).
  const cx = w / 2 - (cup.relX / 2.2) * (w / 2 - 28);
  const cy = h / 2 - (cup.relZ / 2.1) * (h / 2 - 44) - 4;
  return { cx, cy };
}

function initRackMinimap() {
  ctx.rackCanvas = document.getElementById('rack-canvas') as HTMLCanvasElement;
  if (!ctx.rackCanvas) return;
  ctx.rackCtx = ctx.rackCanvas.getContext('2d') as CanvasRenderingContext2D;

  ctx.rackCanvas.addEventListener('click', (e) => {
    const rect = ctx.rackCanvas!.getBoundingClientRect();
    const clickX = e.clientX - rect.left;
    const clickY = e.clientY - rect.top;

    // Find clicked cup
    const w = ctx.rackCanvas!.width;
    const h = ctx.rackCanvas!.height;

    let closestCup: CupData | undefined;
    let minDist = 30 * 30; // click radius squared

    ctx.cups.forEach((cup) => {
      if (cup.isSunk) return;
      const { cx, cy } = getMinimapCupCoords(cup, w, h);

      const d2 = (clickX - cx) ** 2 + (clickY - cy) ** 2;
      if (d2 < minDist) {
        minDist = d2;
        closestCup = cup;
      }
    });

    if (closestCup) {
      ctx.state.selectedCupId = closestCup.id;
      ctx.state.aimAngleDeg = 0;
      updateAimToSelectedCup();
      playAudio('click');
    }
  });
}

function renderCupSelectorStrip() {
  const strip = document.getElementById('cup-selector-strip');
  if (!strip) return;
  strip.innerHTML = '';

  const isTargetBlue = (ctx.state.mode === 'versus' && ctx.state.activePlayerIndex === 0);
  const ownerClass = isTargetBlue ? 'owned-blue' : 'owned-red';
  const iconClass = isTargetBlue ? 'blue' : 'red';
  const basePts = getBasePointsForDistance(ctx.state.distanceYards);
  const swishPts = basePts + Math.round(basePts * 0.5);

  ctx.cups.forEach((cup) => {
    const pill = document.createElement('div');
    const isSelected = cup.id === ctx.state.selectedCupId && !cup.isSunk;
    pill.className = `flag-pill ${isSelected ? 'active' : ''} ${cup.isSunk ? '' : ownerClass}`;
    pill.style.opacity = cup.isSunk ? '0.42' : '1';

    const distMeters = Math.hypot(cup.worldPos.x - ctx.startPoint.x, cup.worldPos.z - ctx.startPoint.z);
    const distYds = Math.round(UnitConversions.metersToYards(distMeters));
    const statusText = cup.isSunk ? 'SUNK' : `+${swishPts}`;
    const statusColor = cup.isSunk ? '' : (isTargetBlue ? 'blue' : 'red');

    pill.innerHTML = `
      <span class="at-flag-icon ${cup.isSunk ? 'open' : iconClass}">&#129380;</span>
      <span class="at-cell-num">#${cup.id}</span>
      <span class="at-cell-dist">${distYds} yd</span>
      <span class="at-cell-rec ${statusColor}">${statusText}</span>
    `;

    pill.addEventListener('click', () => {
      if (cup.isSunk) return;
      ctx.state.selectedCupId = cup.id;
      ctx.state.aimAngleDeg = 0;
      updateAimToSelectedCup();
      renderCupSelectorStrip();
      playAudio('click');
    });
    strip.appendChild(pill);
  });
}

function drawRackMinimap() {
  if (!ctx.rackCtx || !ctx.rackCanvas) return;
  const c = ctx.rackCtx;
  const w = ctx.rackCanvas.width;
  const h = ctx.rackCanvas.height;
  const cxCenter = w / 2;
  const cyCenter = h / 2;
  const radius = Math.min(cxCenter, cyCenter) - 1;

  c.clearRect(0, 0, w, h);

  c.save();
  c.beginPath();
  c.arc(cxCenter, cyCenter, radius, 0, Math.PI * 2);
  c.clip();

  // 1. Deep Forest Perimeter Background
  const bgGrad = c.createRadialGradient(cxCenter, cyCenter, radius * 0.2, cxCenter, cyCenter, radius);
  bgGrad.addColorStop(0.0, '#2e6f34');
  bgGrad.addColorStop(0.72, '#1b4721');
  bgGrad.addColorStop(1.0, '#0d2612');
  c.fillStyle = bgGrad;
  c.fillRect(0, 0, w, h);

  // 2. Fairway Mowing Stripes
  c.lineWidth = 8;
  for (let y = -20; y < h + 20; y += 16) {
    c.strokeStyle = 'rgba(255, 255, 255, 0.05)';
    c.beginPath();
    c.moveTo(cxCenter - 85, y);
    c.lineTo(cxCenter + 85, y - 16);
    c.stroke();
  }

  // 3. Forest Tree Canopy Bumps around Perimeter
  for (let i = 0; i < 24; i++) {
    const ang = (i / 24) * Math.PI * 2;
    const dist = radius - 5 - (i % 3) * 4;
    c.beginPath();
    c.arc(cxCenter + Math.cos(ang) * dist, cyCenter + Math.sin(ang) * dist, 10 + (i % 3) * 2, 0, Math.PI * 2);
    c.fillStyle = i % 2 === 0 ? 'rgba(15, 44, 20, 0.85)' : 'rgba(25, 64, 30, 0.78)';
    c.fill();
  }

  // 4. Tournament Beer Pong Deck Silhouette in Center
  c.fillStyle = 'rgba(15, 23, 42, 0.88)';
  c.strokeStyle = 'rgba(56, 189, 248, 0.55)';
  c.lineWidth = 1.5;
  c.beginPath();
  c.roundRect(26, 20, w - 52, h - 46, 12);
  c.fill();
  c.stroke();

  // Dotted Aim Line from Bottom Tee Indicator to Selected Cup
  const selectedCup = ctx.cups.find((cup) => cup.id === ctx.state.selectedCupId && !cup.isSunk) || ctx.cups[0];
  if (selectedCup) {
    const { cx: tx, cy: ty } = getMinimapCupCoords(selectedCup, w, h);
    c.strokeStyle = 'rgba(255, 255, 255, 0.65)';
    c.lineWidth = 1.5;
    c.setLineDash([3, 3]);
    c.beginPath();
    c.moveTo(cxCenter, h - 14);
    c.lineTo(tx, ty);
    c.stroke();
    c.setLineDash([]);
  }

  // Cup color based on target rack
  const isTargetBlue = (ctx.state.mode === 'versus' && ctx.state.activePlayerIndex === 0);
  const cupFillColor = isTargetBlue ? '#0284c7' : '#ef4444';

  // 5. Draw All 10 Solo Cups
  ctx.cups.forEach((cup) => {
    const { cx, cy } = getMinimapCupCoords(cup, w, h);
    const cupR = 14.5;

    if (cup.isSunk) {
      c.fillStyle = 'rgba(15, 23, 42, 0.55)';
      c.strokeStyle = 'rgba(255, 255, 255, 0.14)';
      c.lineWidth = 1;
      c.beginPath();
      c.arc(cx, cy, cupR, 0, Math.PI * 2);
      c.fill();
      c.stroke();
    } else {
      const isSelected = cup.id === ctx.state.selectedCupId;

      c.fillStyle = cupFillColor;
      c.beginPath();
      c.arc(cx, cy, cupR, 0, Math.PI * 2);
      c.fill();

      c.fillStyle = '#d97706';
      c.beginPath();
      c.arc(cx, cy, cupR - 3, 0, Math.PI * 2);
      c.fill();

      c.fillStyle = '#ffffff';
      c.font = '900 10px -apple-system, sans-serif';
      c.textAlign = 'center';
      c.textBaseline = 'middle';
      c.fillText(`${cup.id}`, cx, cy);

      if (isSelected) {
        c.strokeStyle = '#facc15';
        c.lineWidth = 2.2;
        c.beginPath();
        c.arc(cx, cy, cupR + 2.5, 0, Math.PI * 2);
        c.stroke();
      }
    }
  });

  // 6. Tee Marker at Bottom
  c.beginPath();
  c.arc(cxCenter, h - 12, 4, 0, Math.PI * 2);
  c.fillStyle = '#facc15';
  c.fill();

  c.restore();
  renderCupSelectorStrip();
}

// ============================================================================
// Shot Detection, Live Telemetry & Sinking Logic (1 Cup Per Sink)
// ============================================================================

function updateLiveTelemetry(ballPos?: THREE.Vector3) {
  const shot = ctx.lastShotData;
  if (shot) {
    const speedEl = document.getElementById('tm-speed');
    const vlaEl = document.getElementById('tm-vla');
    const hlaEl = document.getElementById('tm-hla');
    const spinEl = document.getElementById('tm-spin');

    if (speedEl) speedEl.textContent = `${Math.round(Number(shot.ballSpeed || 0))}`;
    if (vlaEl) vlaEl.textContent = `${Number(shot.verticalLaunchAngle || 0).toFixed(1)}°`;
    if (hlaEl) {
      const hla = Number(shot.horizontalLaunchAngle || 0);
      const dir = hla < -0.05 ? 'L' : hla > 0.05 ? 'R' : '';
      hlaEl.textContent = `${Math.abs(hla).toFixed(1)}° ${dir}`;
    }
    if (spinEl) {
      const spin = Math.round(Number(shot.spinSpeed ?? (shot as any).totalSpin ?? 0));
      spinEl.textContent = `${spin}`;
    }
  }

  if (ballPos) {
    if (ballPos.y > ctx.shotPeakApexMeters) {
      ctx.shotPeakApexMeters = ballPos.y;
    }
    if (ctx.golfBall && !ctx.golfBall.physics.isLanded) {
      ctx.shotCarryMeters = Math.hypot(ballPos.x - ctx.startPoint.x, ballPos.z - ctx.startPoint.z);
    } else if (ctx.shotCarryMeters <= 0.1) {
      ctx.shotCarryMeters = Math.hypot(ballPos.x - ctx.startPoint.x, ballPos.z - ctx.startPoint.z);
    }

    const apexFeet = Math.round(UnitConversions.metersToFeet(ctx.shotPeakApexMeters));
    const carryYds = UnitConversions.metersToYards(ctx.shotCarryMeters);
    // Offline relative to aim line (+X is Left, -X is Right)
    const aimDx = ctx.aimPoint.x - ctx.startPoint.x;
    const aimDz = ctx.aimPoint.z - ctx.startPoint.z;
    const aimLen = Math.hypot(aimDx, aimDz) || 1;
    const lateralMeters = ((ballPos.x - ctx.startPoint.x) * aimDz - (ballPos.z - ctx.startPoint.z) * aimDx) / aimLen;
    const offlineYds = UnitConversions.metersToYards(lateralMeters);

    const apexEl = document.getElementById('tm-apex');
    const carryEl = document.getElementById('tm-carry');
    const offlineEl = document.getElementById('tm-offline');

    if (apexEl) apexEl.textContent = `${apexFeet}ft`;
    if (carryEl) carryEl.textContent = `${Math.round(carryYds)}`;
    if (offlineEl) {
      const offDir = offlineYds > 0.05 ? 'L' : offlineYds < -0.05 ? 'R' : '';
      offlineEl.textContent = Math.abs(offlineYds) < 0.1 ? '0.0' : `${Math.abs(offlineYds).toFixed(1)} ${offDir}`;
    }
  }
}

function updateShotTracer(_ballPos: THREE.Vector3) {
  if (ctx.tracerLine) {
    ctx.tracerLine.visible = false;
  }
}

function checkBallCollisions() {
  if (!ctx.golfBall || !ctx.golfBall.isShotActive) return;

  const ballPos = ctx.golfBall.getPosition();
  updateLiveTelemetry(ballPos);
  updateShotTracer(ballPos);

  // CRITICAL SAFETY: Ball must have traveled at least 5m from tee before cup collision can trigger
  if (ballPos.z < 5.0) {
    ctx.prevBallPos.copy(ballPos);
    return;
  }

  const scale = getScaleForDistance(ctx.state.distanceYards);
  const tableTopY = TABLE_HEIGHT;
  const currentTableWidth = TABLE_WIDTH * scale;
  const currentTableLength = TABLE_LENGTH * Math.min(scale, 4.0);
  const rampLength = 3.0 * Math.max(1, scale * 0.7);

  // 1. Runway Surface Contact / Bounce Detection:
  const relX = ballPos.x;
  const relZ = ballPos.z - ctx.tableCenterPos.z;

  if (
    !ctx.state.tableBouncedThisShot &&
    Math.abs(relX) <= currentTableWidth / 2 &&
    relZ >= -currentTableLength / 2 - rampLength &&
    relZ <= currentTableLength / 2 &&
    ballPos.y >= tableTopY - 0.14 &&
    (ballPos.y <= tableTopY + 0.18 * Math.max(1, scale * 0.4) || ctx.golfBall.physics.isLanded)
  ) {
    ctx.state.tableBouncedThisShot = true;
    playAudio('table_bounce');
  }

  // 2. Swept 3D Segment Giant Flush Sunken Cup Roll-In / Swish Detection:
  // Using swept segment (prevBallPos -> ballPos) prevents high-speed shots (150y-200y) from tunneling past cups,
  // and strict lower bound (closestY >= tableTopY - 0.12) prevents balls on the grass under the table (y=0.02) from triggering false sinks.
  const cupTopRadius = CUP_TOP_RADIUS * scale;
  const segX = ballPos.x - ctx.prevBallPos.x;
  const segY = ballPos.y - ctx.prevBallPos.y;
  const segZ = ballPos.z - ctx.prevBallPos.z;
  const segLenXZSq = segX * segX + segZ * segZ;

  for (const cup of ctx.cups) {
    if (cup.isSunk) continue;

    let t = 1.0;
    if (segLenXZSq > 1e-8) {
      t = THREE.MathUtils.clamp(
        ((cup.worldPos.x - ctx.prevBallPos.x) * segX + (cup.worldPos.z - ctx.prevBallPos.z) * segZ) / segLenXZSq,
        0,
        1
      );
    }

    const closestX = ctx.prevBallPos.x + segX * t;
    const closestY = ctx.prevBallPos.y + segY * t;
    const closestZ = ctx.prevBallPos.z + segZ * t;
    const distXZ = Math.hypot(closestX - cup.worldPos.x, closestZ - cup.worldPos.z);

    // Lower bound: 0.36m (strictly above grass Y=0.021m at all distances)
    // Upper bound: scales with cup size (slightly more generous on runway bounce hops)
    const minSinkY = tableTopY - 0.12;
    const maxSinkY = tableTopY + (ctx.state.tableBouncedThisShot ? 0.46 : 0.34) * scale;

    if (closestY >= minSinkY && closestY <= maxSinkY && distXZ <= cupTopRadius + 0.04 * scale) {
      // Cup Rim Clink Check (near rim edge)
      if (Math.abs(distXZ - cupTopRadius) < 0.06 * scale && Math.abs(closestY - tableTopY) < 0.14 * scale) {
        playAudio('cup_rim');
      }

      // Ball drops in / rolls in over the rim:
      if (distXZ < cupTopRadius - 0.015 * scale) {
        ctx.prevBallPos.copy(ballPos);
        handleCupSunk(cup, ctx.state.tableBouncedThisShot);
        return;
      }
    }
  }

  ctx.prevBallPos.copy(ballPos);
}

function handleCupSunk(cup: CupData, wasBounceShot: boolean) {
  if (ctx.state.sunkThisShot) return;
  ctx.state.sunkThisShot = true;

  // Sinks ONLY this 1 cup
  cup.isSunk = true;
  ctx.state.totalSunk++;
  ctx.state.currentStreak++;
  if (ctx.state.currentStreak > ctx.state.bestStreak) {
    ctx.state.bestStreak = ctx.state.currentStreak;
  }

  const activePlayer = ctx.state.players[ctx.state.activePlayerIndex];
  activePlayer.cupsSunk++;

  const scale = getScaleForDistance(ctx.state.distanceYards);

  // Big Explosive 3D Splash & Expanding Shockwave Ring
  const splashOrigin = cup.worldPos.clone().setY(TABLE_HEIGHT + 0.02 * scale);
  ctx.particleSystem?.spawnBeerSplash(splashOrigin, 110, scale);

  // Pop cup scale and flash halo
  const meshRef = ctx.cupMeshes[cup.id - 1];
  if (meshRef?.outerMesh) {
    meshRef.outerMesh.scale.set(1.24, 1.24, 1.24);
  }

  // Camera impact trauma
  cameraTrauma = 0.12;

  // If on a streak or direct swish: shoot victory celebration fireworks!
  if (ctx.state.currentStreak >= 2 || !wasBounceShot) {
    ctx.particleSystem?.spawnCelebrationFireworks(splashOrigin, activePlayer.team, 180);
  }

  // Audio & Scoring
  playAudio('cup_sink');

  const basePts = getBasePointsForDistance(ctx.state.distanceYards);

  if (wasBounceShot) {
    ctx.state.bounceShots++;
    activePlayer.score += basePts;
    showEventToast(
      'RUNWAY ROLL-IN SINK!',
      `Cup #${cup.id} Eliminated!`,
      `+${basePts} PTS`
    );
  } else {
    // Direct swish bonus (+50% bonus points)
    const swishBonus = Math.round(basePts * 0.5);
    activePlayer.score += basePts + swishBonus;
    showEventToast(
      'DIRECT SWISH! 🎯',
      `Cup #${cup.id} Clean Swish!`,
      `+${basePts + swishBonus} PTS (BONUS)`
    );
  }

  // Play crowd cheer
  setTimeout(() => playAudio('cheer'), 180);

  // Check victory condition on active target rack
  const remainingCount = ctx.cups.filter((c) => !c.isSunk).length;
  if (remainingCount === 0) {
    handleVictory();
  } else {
    // Select next open cup as target
    updateAimToSelectedCup();
  }

  // Smooth ball plunge: Freeze physics, keep ball VISIBLE and animate it plunging into cup liquid
  if (ctx.golfBall) {
    ctx.golfBall.physics.freeze();
    ctx.golfBall.isShotActive = false;

    activeBallPlunge = {
      startPos: ctx.golfBall.object.position.clone(),
      targetPos: new THREE.Vector3(cup.worldPos.x, TABLE_HEIGHT - 0.02 * scale, cup.worldPos.z),
      progress: 0,
      scale: scale,
    };

    if (shotEndTimer) clearTimeout(shotEndTimer);
    shotEndTimer = setTimeout(() => {
      shotEndTimer = null;
      activeBallPlunge = null;
      handleShotEnd();
    }, 2400);
  }

  updateHUD();
}

let shotEndTimer: ReturnType<typeof setTimeout> | null = null;
let shotSafetyTimer: ReturnType<typeof setTimeout> | null = null;
let isHandlingShotEnd = false;

function handleShotEnd() {
  if (isHandlingShotEnd) return;
  isHandlingShotEnd = true;

  if (shotSafetyTimer) {
    clearTimeout(shotSafetyTimer);
    shotSafetyTimer = null;
  }

  if (shotEndTimer) {
    clearTimeout(shotEndTimer);
    shotEndTimer = null;
  }

  ctx.state.totalShots++;
  ctx.state.currentTurnShots++;

  if (!ctx.state.sunkThisShot) {
    // Miss / Airball
    ctx.state.currentStreak = 0;
    playAudio('airball');
    showEventToast('MISS!', 'No cup sank this shot', 'RESET FOR SHOT 2');
  }

  // Check turn progression
  if (ctx.state.currentTurnShots >= ctx.state.maxShotsPerTurn) {
    // Turn complete -> switch player in versus mode
    if (ctx.state.mode === 'versus') {
      ctx.state.activePlayerIndex = (ctx.state.activePlayerIndex + 1) % ctx.state.players.length;
      // Switch active target rack:
      // Player 1 (Red) shoots at blueRack; Player 2 (Blue) shoots at redRack
      ctx.cups = ctx.state.activePlayerIndex === 0 ? ctx.blueRack : ctx.redRack;
      positionTableAndCups(ctx.state.distanceYards);
      syncCupMeshesWithActiveRack();
      updateAimToSelectedCup();

      const nextPlayer = ctx.state.players[ctx.state.activePlayerIndex];
      const targetTeamName = nextPlayer.team === 'red' ? 'Blue' : 'Red';
      showEventToast('TURN SWITCH', `${nextPlayer.name}'s Turn! (${targetTeamName} Cups)`, 'GET READY');
    }
    ctx.state.currentTurnShots = 0;
  }

  // If a cup was sunk this shot, refresh table deck geometry to seal the sunken cup
  if (ctx.state.sunkThisShot) {
    positionTableAndCups(ctx.state.distanceYards);
  }

  // Reset shot flags
  ctx.state.tableBouncedThisShot = false;
  ctx.state.sunkThisShot = false;

  // Reset ball to tee and restore static camera view
  if (ctx.golfBall) {
    ctx.golfBall.isShotActive = false;
    ctx.golfBall.physics.freeze();
    ctx.golfBall.reset(ctx.aimPoint, ctx.startPoint);
  }

  if (ctx.camera) {
    ctx.camera.isTracking = false;
    ctx.camera.setPositions(ctx.startPoint, ctx.aimPoint);
  }

  // Re-aim at target
  updateAimToSelectedCup();
  updateHUD();

  setTimeout(() => {
    isHandlingShotEnd = false;
  }, 200);
}

function handleVictory() {
  ctx.state.isGameOver = true;
  playAudio('win');

  const winner = ctx.state.players[ctx.state.activePlayerIndex];
  const acc = ctx.state.totalShots > 0
    ? Math.round((ctx.state.totalSunk / ctx.state.totalShots) * 100)
    : 100;

  const modal = document.getElementById('modal-victory');
  const winnerEl = document.getElementById('v-winner-name');
  const shotsEl = document.getElementById('v-total-shots');
  const accEl = document.getElementById('v-accuracy');
  const bounceEl = document.getElementById('v-bounce-shots');

  if (winnerEl) winnerEl.textContent = winner.name;
  if (shotsEl) shotsEl.textContent = `${ctx.state.totalShots}`;
  if (accEl) accEl.textContent = `${acc}%`;
  if (bounceEl) bounceEl.textContent = `${ctx.state.bounceShots}`;
  if (modal) modal.style.display = 'flex';

  // Grand Victory Fireworks
  ctx.particleSystem?.spawnCelebrationFireworks(ctx.tableCenterPos, winner.team, 240);
  setTimeout(() => {
    ctx.particleSystem?.spawnCelebrationFireworks(ctx.tableCenterPos.clone().add(new THREE.Vector3(-3, 1, 0)), winner.team, 180);
    ctx.particleSystem?.spawnCelebrationFireworks(ctx.tableCenterPos.clone().add(new THREE.Vector3(3, 1, 0)), winner.team, 180);
  }, 450);
}

function resetGame() {
  ctx.state.isGameOver = false;
  ctx.state.totalShots = 0;
  ctx.state.totalSunk = 0;
  ctx.state.bounceShots = 0;
  ctx.state.currentStreak = 0;
  ctx.state.currentTurnShots = 0;
  ctx.state.isReracked = false;
  ctx.state.tableBouncedThisShot = false;
  ctx.state.sunkThisShot = false;

  ctx.state.players.forEach((p) => {
    p.cupsSunk = 0;
    p.score = 0;
  });

  const defaultPyramid = createPyramidLayout();

  // Reset both racks
  const resetRackData = (rack: CupData[]) => {
    rack.forEach((cup, idx) => {
      cup.isSunk = false;
      cup.sinkAnimProgress = 0;
      cup.relX = defaultPyramid[idx].relX;
      cup.relZ = defaultPyramid[idx].relZ;
    });
  };

  resetRackData(ctx.redRack);
  resetRackData(ctx.blueRack);

  // Active target rack: in versus mode Player 1 shoots at Blue rack
  ctx.cups = (ctx.state.mode === 'versus' && ctx.state.activePlayerIndex === 0)
    ? ctx.blueRack
    : ctx.redRack;

  // Restore 3D meshes
  const scale = getScaleForDistance(ctx.state.distanceYards);
  ctx.cupMeshes.forEach((meshRef, idx) => {
    const cup = ctx.cups[idx];
    cup.meshGroup = meshRef.group;
    cup.liquidMesh = meshRef.liquidMesh;
    cup.rimRingMesh = meshRef.rimRingMesh;
    cup.haloMesh = meshRef.haloMesh;

    meshRef.group.visible = true;
    meshRef.group.scale.set(scale, scale, scale);
    meshRef.liquidMesh.position.y = -0.07;
    (meshRef.rimRingMesh.material as THREE.MeshStandardMaterial).opacity = 1.0;
    (meshRef.haloMesh.material as THREE.MeshBasicMaterial).opacity = 0.0;
  });

  syncCupMeshesWithActiveRack();
  positionTableAndCups(ctx.state.distanceYards);

  const modal = document.getElementById('modal-victory');
  if (modal) modal.style.display = 'none';

  updateAimToSelectedCup();
  updateHUD();
}

